const data = $input.first().json;
const projectRows = Object.entries(data.by_project || {}).map(([name, hours]) => `<tr><td>${name}</td><td>${hours}h</td></tr>`).join('');
const tagRows = Object.entries(data.by_tag || {}).map(([name, hours]) => `<tr><td>${name}</td><td>${hours}h</td></tr>`).join('');
const dayRows = Object.entries(data.by_day || {}).map(([day, hours]) => `<tr><td>${day}</td><td>${hours}h</td></tr>`).join('');

const html = `
<h2>Weekly Time Tracking Summary</h2>
<p>${data.start_date} to ${data.end_date}</p>
<p><strong>Total: ${data.total_hours}h</strong></p>

<h3>By Project</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse">${projectRows}</table>

<h3>By Tag</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse">${tagRows}</table>

<h3>By Day</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse">${dayRows}</table>
`;

return [{ json: { subject: `Time Tracking: ${data.total_hours}h (${data.start_date} to ${data.end_date})`, html } }];
